using System;

public class Program
{
    public static void Main()
    {
        int n = int.Parse(Console.ReadLine());
        double p = double.Parse(Console.ReadLine());
        double total = n * p;
        if (n > 10)
            total = total * 0.8;
        else if (n >= 5)
            total = total * 0.9;
        Console.WriteLine(Math.Round(total, 2));
    }
}

