public class Program
{
    public static void Main()
    {
        int n = int.Parse(Console.ReadLine());
        bool even = n % 2 == 0, five = n % 5 == 0;
        if (even && five)
            Console.WriteLine("Even and divisible by 5");
        else if (even)
            Console.WriteLine("Even but not divisible by 5");
        else if (five)
            Console.WriteLine("Divisible by 5 but not even");
        else
            Console.WriteLine("Neither even nor divisible by 5");
    }
}

