        double s = h * rate;
        double tax = 0;
        if (s > 7000)
            tax = 400 + (s - 7000) * 0.35;
        else if (s >= 4500)
            tax = (s - 4500) * 0.2;
        Console.WriteLine(Math.Round(s - tax, 2));
    }
