using System;

public class Program
{
    public static void Main()
    {
        int day = int.Parse(Console.ReadLine());
        int hours = int.Parse(Console.ReadLine());
        int low, high;
        if (day == 7) { low = 40; high = 50; }
        else if (day >= 2 && day <= 5) { low = 25; high = 30; }
        else { low = 30; high = 35; }
        int pay = hours <= 8 ? hours * low : 8 * low + (hours - 8) * high;
        Console.WriteLine(pay);
    }
}

